SELECT sub.sm_ship_mode_id, sub.sm_carrier, sub.avg_discount, sub.sales_cnt, sub.discount_category, sub.store_avg_net_paid FROM (SELECT sm.sm_ship_mode_id, sm.sm_carrier, AVG(cs.cs_ext_discount_amt) AS avg_discount, COUNT(*) AS sales_cnt, CASE WHEN AVG(cs.cs_ext_discount_amt) > 2000 THEN 'HIGH_DISCOUNT' ELSE 'LOW_DISCOUNT' END AS discount_category, ROW_NUMBER() OVER (ORDER BY AVG(cs.cs_ext_discount_amt) DESC) AS rn, COALESCE(st.store_avg_net_paid, 0) AS store_avg_net_paid FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk LEFT JOIN (SELECT ss.ss_hdemo_sk, AVG(ss.ss_net_paid) AS store_avg_net_paid FROM store_sales ss GROUP BY ss.ss_hdemo_sk) st ON hd.hd_demo_sk = st.ss_hdemo_sk WHERE hd.hd_income_band_sk BETWEEN 3 AND 7 GROUP BY sm.sm_ship_mode_id, sm.sm_carrier, st.store_avg_net_paid HAVING COUNT(*) >= 10) sub WHERE rn <= 3 ORDER BY avg_discount DESC
